return msg;

// Refuses a call PaperGo did not sign: PaperGo-Signature is
// t=<unix time>,v1=<hex HMAC-SHA256 of "t.subject.workspace.body">, keyed
// with the connection's signing secret.
const secret = env.get("PAPERGO_SIGNING_SECRET");
const h = msg.req.headers;
const [t, v1] = String(h["papergo-signature"] || "").replace(/^t=/, "").split(",v1=");
const body = msg.payload === undefined || msg.payload === "" ? "" : typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload);
const signed = `${t}.${h["papergo-subject"] || ""}.${h["papergo-workspace"] || ""}.${body}`;
const expected = secret ? crypto.createHmac("sha256", secret).update(signed).digest("hex") : "";
const fresh = Math.abs(Date.now() / 1000 - Number(t)) <= 300;
if (!secret || !v1 || v1.length !== expected.length || !fresh || !crypto.timingSafeEqual(Buffer.from(v1), Buffer.from(expected))) {
  msg.statusCode = 401;
  msg.payload = { error: "not signed by PaperGo" };
  return [null, msg];
}
// A repeated Idempotency-Key is a call already done: answer it again.
const key = h["idempotency-key"];
const done = flow.get("done") || {};
if (key && done[key]) {
  msg.payload = done[key];
  return [null, msg];
}
msg.caller = h["papergo-subject"];
msg.idempotencyKey = key;
return [msg, null];

const minutes = Math.min(Math.max(Number(msg.payload && msg.payload.minutes) || 30, 5), 120);
const until = new Date(Date.now() + minutes * 60000).toISOString();
const heating = Object.assign({ mode: "auto", target_c: 21 }, flow.get("heating"), { mode: "boost", boost_until: until });
flow.set("heating", heating);
node.log(`boost for ${minutes} minutes, asked by ${msg.caller}`);
msg.payload = { heating };
if (msg.idempotencyKey) {
  const done = flow.get("done") || {};
  done[msg.idempotencyKey] = msg.payload;
  flow.set("done", done);
}
return msg;
